const assert = require('node:assert/strict');
const { Pool } = require('pg');

// This descriptor is generated by the disposable runner, never assembled from
// application environment variables. Reject extra keys rather than forwarding pg options.
function validateContext(value) {
    const keys = ['host', 'port', 'database', 'user', 'password'];
    if (!value || Object.keys(value).sort().join() !== keys.sort().join() ||
        value.host !== '127.0.0.1' || !Number.isInteger(value.port) ||
        value.port < 1 || value.port > 65535 ||
        !/^gnosis_migration_test_[a-f0-9]{16}$/.test(value.database) ||
        !/^gnosis_app_[a-f0-9]{16}$/.test(value.user) ||
        value.database.slice(-16) !== value.user.slice(-16) ||
        !/^synthetic-[a-f0-9]{32}$/.test(value.password)) {
        throw new Error('Invalid disposable application test context.');
    }
    return { host: value.host, port: value.port, database: value.database,
        user: value.user, password: value.password };
}

function contextFromEnvironment() {
    if (process.env.GNOSIS_TEST_ISOLATION !== '1') {
        throw new Error('Use the disposable database runner.');
    }
    let value;
    try { value = JSON.parse(process.env.GNOSIS_APPLICATION_TEST_CONTEXT); }
    catch { throw new Error('Use the disposable database runner.'); }
    return validateContext(value);
}

async function verifyIdentity(client, context) {
    const result = await client.query(`SELECT current_user AS username,
        current_database() AS database, rolsuper, rolcreatedb, rolcreaterole,
        rolreplication, rolbypassrls, rolcanlogin, rolinherit
        FROM pg_roles WHERE rolname=current_user`);
    assert.deepEqual(result.rows, [{ username: context.user, database: context.database,
        rolsuper: false, rolcreatedb: false, rolcreaterole: false,
        rolreplication: false, rolbypassrls: false, rolcanlogin: true, rolinherit: false }]);
    assert.equal((await client.query(`SELECT count(*)::int AS count FROM pg_auth_members
        WHERE member=(SELECT oid FROM pg_roles WHERE rolname=current_user)`)).rows[0].count, 0);
}

async function createTestPool(value) {
    const context = validateContext(value);
    const pool = new Pool({ ...context, max: 5, connectionTimeoutMillis: 5000,
        idleTimeoutMillis: 1000, statement_timeout: 10000, lock_timeout: 3000,
        application_name: 'gnosis-application-tests', options: '-c search_path=public', ssl: false });
    const clients = new Set();
    const connect = pool.connect.bind(pool);
    let idleFailure = false;
    let closePromise;
    pool.on('error', () => { idleFailure = true; });
    // Track both callback (pool.query) and promise acquisitions without changing
    // pg's transaction semantics. Cleanup destroys any unreleased clients.
    function track(client) {
        const release = client.release.bind(client);
        let released = false;
        clients.add(client);
        client.release = error => {
            if (released) return;
            released = true;
            clients.delete(client);
            release(error);
        };
        return client;
    }
    pool.connect = callback => {
        if (callback) return connect((error, client) => {
            if (error) return callback(error);
            track(client);
            callback(null, client, client.release);
        });
        return connect().then(track);
    };
    async function close() {
        if (!closePromise) closePromise = (async () => {
            for (const client of [...clients]) client.release(true);
            await pool.end();
            if (idleFailure) throw new Error('Disposable application pool had an idle connection failure.');
        })();
        return closePromise;
    }
    try { await withClient(pool, client => verifyIdentity(client, context)); }
    catch (error) { await close().catch(() => {}); throw error; }
    return { pool, close };
}

async function withClient(pool, callback) {
    const client = await pool.connect();
    try { return await callback(client); }
    finally { client.release(); }
}

async function withTransaction(pool, callback) {
    return withClient(pool, async client => {
        await client.query('BEGIN');
        try {
            const result = await callback(client);
            await client.query('COMMIT');
            return result;
        } catch (error) {
            try { await client.query('ROLLBACK'); }
            catch { client.release(true); }
            throw error;
        }
    });
}

function installApplicationPool(pool) {
    const id = require.resolve('../../src/db/db');
    if (require.cache[id]) throw new Error('Install the application test pool before importing application code.');
    require.cache[id] = { id, filename: id, loaded: true, exports: pool };
}

module.exports = { validateContext, contextFromEnvironment, verifyIdentity,
    createTestPool, withClient, withTransaction, installApplicationPool };
